def extostr(e, max_level=30, max_path_level=5):
    msg = f"{type(e).__name__}: {e}"
    for i in range(min(max_level, len(inspect.traceback.extract_stack()))):
        if i == 0:
            msg += f"\nCalled from: {inspect.traceback.extract_stack()[i][2]}:{inspect.traceback.extract_stack()[i][1]}"
        else:
            msg += f"\n    Called from: {inspect.traceback.extract_stack()[i][2]}:{inspect.traceback.extract_stack()[i][1]}"
    if len(inspect.traceback.extract_stack()) - 1 > max_path_level:
        msg += f"\nand {len(inspect.traceback.extract_stack()) - max_path_level - 1} more..."
    return msg

def extostr(e, max_level = 30, max_path_level = 5):
    if not isinstance(e, Exception):
        raise TypeError("'e' must be an instance of Exception")
    if not isinstance(max_level, int):
        raise TypeError("'max_level' must be an integer")
    if not isinstance(max_path_level, int):
        raise TypeError("'max_path_level' must be an integer")

    # initialize the output string
    output = ""

    # add the exception type and message
    output += f"{e.__class__.__name__}: {e}"

    # add the call stack information
    output += "\nCall Stack:"
    for frame in inspect.stack()[:max_level]:
        if frame[3] != "<module>":
            output += f"\n{frame[3]}:{frame[2]}:{frame[1]}"

    # add the exception path information
    output += "\nException Path:"
    for obj in e.__traceback__.tb_frame.f_locals.values():
        if isinstance(obj, Exception):
            output += f"\n{obj.__class__.__name__}: {obj}"

    return output

