def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extracts the number and supplement from the content of <issue>xxxx</issue>.
    Supported values:
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl 1, 25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12, s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl, suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """

    # Match the number and supplement from the issue content
    pattern = r"(\d*)\s*((suppl|special|s(\d*))\.?\.?)"
    match = re.search(pattern, issue.text_content())

    if match:
        number = match.group(1)
        supplement = match.group(2)

        return (number, supplement)
    else:
        return (None, None)

