    if isinstance(commands, str):
        commands = [commands]
    if env:
        env = {**os.environ, **env}
    try:
        for command in commands:
            if verbose:
                print(f"Running command: {command}")
            process = subprocess.Popen(command, args, cwd, env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True)
            output, error = process.communicate()
            if verbose:
                print(f"Output: {output.decode()}")
                print(f"Error: {error.decode()}")
            if hide_stderr:
