def paging(response, max_results):
    current_result = 0
    while True:
        end_result = current_result + max_results
        if end_result > len(response):
            end_result = len(response)
        page = response[current_result:end_result]
        if len(page) == 0:
            break
        yield page
        current_result += max_results

def paging(response, max_results):
    # Create an iterator over the response
    response_iterator = iter(response)

    # Get the first page
    current_page = next(response_iterator)

    while current_page is not None:
        # Yield the current page
        yield current_page

        # Get the next page from the iterator
        try:
            current_page = next(response_iterator)
        except StopIteration:
            current_page = None

