def get_ignored_files(ignored):
    """
    Use the `git ls-files` command to obtain the list of files,
    sort the list for only ignored files,
    return those files as a single string with each filename separated by a comma.
    """
    command = "git ls-files --others --exclude-standard"
    result = subprocess.run(command, shell=True, check=True, capture_output=True)
    ignored_files = []
    for line in result.stdout.decode("utf-8").splitlines():
        if line.startswith("!") and line[1:] not in ignored:
            ignored_files.append(line[1:])
    return ", ".join(ignored_files)

