def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    :param graph: A graph object
    :param prop: A URIRef indicating the property to use for the hierarchy
    :param roots: (optional) A set of nodes to consider as roots. If not provided, all nodes in the graph will be considered
    :return: A set of nodes that are the roots of the transitive hierarchy
    """
    if roots is None:
        roots = graph.all_nodes()
    visited = set()
    queue = deque(roots)
    while queue:
        node = queue.popleft()
        if node not in visited:
            visited.add(node)
            for child in graph.all_nodes(node, prop):
                if child not in visited:
                    queue.append(child)
    return visited

