def verify_relayable_signature(public_key, doc, signature):
    import xml.etree.ElementTree as ET

    xml_root = ET.fromstring(doc)
    signed_elements = []

    for element in xml_root.getiterator():
        if element.tag == "SignatureValue":
            signed_elements.append(element)

    # Extract the base64-encoded signature from the first SignatureValue element
    signed_value = base64.b64decode(signed_elements[0].text.encode("utf-8"))

    # Verify the signed elements with the public key and signature
    if not rsa.verify(signed_elements, signature, public_key):
        raise ValueError("Invalid signature")

    # Verify that the signed elements are properly secured against tampering
    for element in signed_elements:
        if element.tag not in ["Reference", "Signature"]:
            raise ValueError("Invalid signed element")

    return True

